(function(){'use strict';
/* Fact Conflict and Contradiction Resolution Signature Database generator — jahdb-fact-conflict-contradiction-resolution-signature-1.0.
   Property of Justin Addam Higgins (JAH).
   Deterministic: same seed always makes the same record.
   Type: Signature-method records (Signature-labeled where speculated). */
function prng(seed){var a=(seed>>>0)||1;return function(){a|=0;a=(a+0x6D2B79F5)|0;var t=Math.imul(a^(a>>>15),1|a);t=(t+Math.imul(t^(t>>>7),61|t))^t;return((t^(t>>>14))>>>0)/4294967296;};}
var PREFIX='JAH-FCCR-SIG-';
var DBTITLE='Fact Conflict and Contradiction Resolution Signature Database';
var DESC='Signature methods for resolving fact conflicts — Signature verification procedures, deterministic reconciliation, and provenance-weighted resolution.';
var CATS=["verification-procedures", "deterministic-reconciliation", "provenance-weighting", "arbitration", "conflict-ledger", "lineage-resolution"];
var SRC='signature';
var SRC_DETAIL='Signature-method record: deterministic Signature reconciliation procedures; labeled signature.';
var REQUIRED=["name", "how_it_works", "key_points", "requirements", "standards", "citations"];
var DATA=[{"topic": "The Signature Principle: Conflicts Are Data, Not Errors", "cat": "verification-procedures", "rank": 1, "tier": "Foundations", "name": "conflicts-are-data", "desc": "The Signature principle reframes fact conflicts: a contradiction is not a defect to delete but a data point about provenance, timing, or perspective that must be preserved and processed. Deleting the losing claim destroys information — about which sources erred, about when the world changed, about where uncertainty lives. Signature reconciliation therefore never deletes; it adjudicates, time-indexes, and archives both sides with the verdict attached. This record states the principle, its three corollaries (preserve both claims, verdicts are timestamped, losing claims remain queryable), and why deletion-based systems keep re-learning the same lessons.", "body": {"how_it_works": "When a conflict is detected, both claims are committed to the conflict ledger as immutable records with hashes, timestamps, and provenance — nothing is overwritten or removed. The reconciliation procedure then produces a verdict record that references both claims by hash and states the outcome: claim A preferred (with margin and reasons), both time-indexed as true in different intervals, or structured abstention. The verdict itself is timestamped and signed, because verdicts can be superseded by new evidence — and when they are, the old verdict remains in history with its supersession record. Losing claims stay queryable with their status (\"superseded by verdict V on date D\") so future analysts can see exactly what was considered and why it lost. The practical effect: the system accumulates knowledge about its own errors, and repeated conflicts get faster because the ledger remembers.", "key_points": ["Never delete a claim in conflict — adjudicate, time-index, archive.", "Verdicts are timestamped records that can themselves be superseded.", "Losing claims stay queryable with status and reasons.", "The ledger of past conflicts accelerates future resolutions."], "requirements": "Immutable claim storage; a verdict record format; queryable status on all claims.", "standards": "Deletion of conflicting claims is prohibited. All verdicts reference both claims by hash.", "citations": ["Signature data governance: DATA LOCK-IN principle", "Immutable history practice (public reference)"]}}, {"topic": "Deterministic Conflict Identification", "cat": "verification-procedures", "rank": 1, "tier": "Foundations", "name": "deterministic-identification", "desc": "Signature conflict identification is deterministic: the same claims, run through the procedure twice, produce the same conflict report every time. No analyst judgment calls in the identification step — normalization rules, comparison tolerances, and conflict-type tests are fixed, ordered, and versioned. This record specifies the identification procedure version 1.0: the normalization order, the exact comparison predicates, and the conflict report format. Determinism matters because it makes conflicts reproducible, reviewable, and machine-checkable — the foundation every later Signature procedure stands on.", "body": {"how_it_works": "Run the fixed identification sequence: (1) normalize both claims with the versioned normalization rules (unit conversion table v1.0, entity alias map v1.0, date normalization to ISO 8601); (2) apply the comparison predicates in order — identity (same claim?), scope-overlap (same entity/attribute/time?), value-compare (within tolerance?); (3) classify with the fixed type tests (exclusivity, tolerance-band, source-level). Each step's output is written to the conflict report with the procedure version stamped on it. Because every rule is fixed and ordered, two analysts — or an analyst and a machine — produce byte-comparable reports from the same input; any difference indicates different input or a procedure violation, both of which are diagnosable. Procedure updates are versioned (1.0 → 1.1) and never applied retroactively: old reports keep their version stamp and remain valid under the version that produced them.", "key_points": ["Fixed, ordered, versioned rules — no judgment calls in identification.", "Same input twice = byte-comparable reports, analyst or machine.", "Report differences diagnose input differences or procedure violations.", "Versioned procedures; old reports stay valid under their version."], "requirements": "Versioned normalization rules; ordered comparison predicates; the conflict report template with version stamp.", "standards": "Identification must be reproducible by a second party. Procedure versions immutable once published.", "citations": ["Signature deterministic procedure standard (Signature-labeled)", "Reproducibility requirements in scientific workflows (public reference)"]}}, {"topic": "Signature Provenance Chains", "cat": "lineage-resolution", "rank": 1, "tier": "Foundations", "name": "signature-provenance-chains", "desc": "A Signature provenance chain is the unbroken, hash-linked record of a claim's journey from observation to the present: who observed, who recorded, who transmitted, who transformed, with a timestamp and hash at every link. This record defines the chain format, the link requirements (each link names its predecessor by hash), and the chain-integrity check that detects breaks, gaps, and forgeries. In Signature resolution, a claim without a verifiable chain is a claim without standing — it may still be true, but it cannot win against a chained claim.", "body": {"how_it_works": "Build the chain backward from the claim: each link records the holder, the action (observed, recorded, transmitted, transformed, cited), the timestamp, and the hash of the previous link — forming a tamper-evident sequence. Run the integrity check: verify every hash link, confirm timestamps are non-decreasing along the chain, and flag gaps (a link whose predecessor is unknown) and breaks (a hash mismatch). A complete chain gives the claim full standing; a chain with gaps gives partial standing proportional to the verified portion; a broken chain gives no standing until repaired by re-sourcing the broken link. Transformations (translations, unit conversions, summaries) are first-class links with their method recorded — a summarized claim's chain shows the summarization, so the information loss is visible. Chains are stored with the claim and travel with it into every reconciliation.", "key_points": ["Hash-linked sequence: holder, action, timestamp, predecessor hash per link.", "Integrity check: hash verification, timestamp order, gap/break detection.", "Standing follows chain completeness: full, partial, or none.", "Transformations are links — information loss stays visible."], "requirements": "The chain link schema; hash-linking implementation; the integrity check procedure.", "standards": "Claims without verifiable chains cannot outrank chained claims. Chain breaks must be repaired by re-sourcing.", "citations": ["Provenance models (W3C PROV, public reference)", "Hash-chained integrity (blockchain-adjacent concepts, public reference)"]}}, {"topic": "The Signature Evidence Ledger", "cat": "conflict-ledger", "rank": 1, "tier": "Foundations", "name": "evidence-ledger", "desc": "The Signature evidence ledger is the single append-only record of every claim, conflict, verdict, and supersession in the system — the institutional memory of what was believed, when, and why. This record defines the ledger's entry types (claim, conflict, verdict, supersession, retraction), the append-only discipline, and the query contract: any question of the form \"what did we hold on date D and why\" must be answerable from the ledger alone. The ledger is what makes Signature resolution auditable years after the fact.", "body": {"how_it_works": "Every claim enters the ledger as a claim entry with its hash, provenance chain reference, and timestamp. When claims conflict, a conflict entry links both claim hashes with the conflict report. The reconciliation verdict is a verdict entry referencing the conflict and stating the outcome with reasons and margin. Later corrections are supersession entries linking old and new, and source withdrawals are retraction entries. Nothing is ever modified or deleted — the ledger only grows, and current belief is computed as the latest non-superseded verdict per claim. The query contract is enforced by the ledger index: claim-by-hash, conflicts-by-claim, verdicts-by-date, and the time-travel query (belief state at any past date, reconstructed from the entries). Quarterly ledger audits verify hash-chain integrity and the completeness of the indexes.", "key_points": ["Five entry types: claim, conflict, verdict, supersession, retraction.", "Append-only: current belief is computed, never edited in place.", "Time-travel queries: belief state at any past date, fully reconstructed.", "Quarterly integrity audits on the hash chain and indexes."], "requirements": "The ledger schema; append-only storage; the four ledger indexes; audit procedure.", "standards": "Ledger edits prohibited. Every belief must trace to ledger entries.", "citations": ["Append-only audit log design (public reference)", "Signature DATA LOCK-IN governance"]}}, {"topic": "Claim Lock-In: Immutable Record History", "cat": "conflict-ledger", "rank": 1, "tier": "Foundations", "name": "claim-lock-in", "desc": "Claim lock-in is the Signature guarantee: once a claim is recorded, its history is immutable — corrections add new records, they never rewrite old ones. This record explains the lock-in mechanism (hash-chained, append-only, no-edit storage), what it protects against (silent revision, history rewriting, accountability evasion), and the correction protocol that keeps locked history usable (supersession links, current-view computation). Lock-in is what lets a contradiction resolved in 2024 still be fully auditable in 2034.", "body": {"how_it_works": "Claims are written to immutable storage addressed by content hash; the write-once guarantee is enforced at the storage layer, not by policy alone. A correction is a new claim record carrying a supersedes link to the old record's hash, plus the reason for correction and the corrector's identity. The current view — what the system believes now — is computed by walking supersession links to the latest non-superseded record per claim lineage; the computation is deterministic and its result is itself hashable for verification. Retractions follow the same pattern with a retraction record type. The no-edit rule has exactly one exception: none — even erroneous entries stay, marked erroneous, because the error's existence is itself historical fact. Storage audits verify immutability by re-hashing and comparing against the recorded hashes.", "key_points": ["Write-once storage: corrections are new records with supersedes links.", "Current belief is computed deterministically from the supersession graph.", "No-edit rule has no exceptions — errors stay, marked erroneous.", "Re-hash audits verify immutability at the storage layer."], "requirements": "Content-addressed immutable storage; the supersession link schema; current-view computation; audit re-hashing.", "standards": "History rewrites are prohibited absolutely. All corrections link their predecessors.", "citations": ["Content-addressed storage (public reference)", "Signature DATA LOCK-IN governance"]}}, {"topic": "Signature Identity Resolution", "cat": "lineage-resolution", "rank": 1, "tier": "Foundations", "name": "signature-identity-resolution", "desc": "Before Signature reconciliation compares claims, it must prove the claims are about the same entity — deterministically. Signature identity resolution replaces judgment-call entity matching with a fixed procedure: canonical identifier lookup first, attribute-signature scoring second, and explicit uncertain status third. This record gives the procedure, the canonical identifier registry rules, and the merge protocol with its mandatory reversibility. Identity mistakes are the most expensive errors in conflict work, so this procedure is deliberately conservative: uncertain means uncertain.", "body": {"how_it_works": "Step one is canonical identifier lookup: if both records carry the same registry identifier (the Signature canonical ID), identity is established — no scoring needed. Step two, for records without shared identifiers, computes the attribute-signature score with the fixed weight table (registry ID 100, national ID 90, exact date+place 60, name match 20, and so on); scores at or above the merge threshold establish identity, scores at or below the split threshold establish distinctness. Step three handles the middle band: records are marked identity-uncertain, linked as candidates, and excluded from conflict comparison — they wait for more evidence rather than being forced. Merges are executed as link records (A and B are the same entity, evidence cited, decider named) and are fully reversible: unmerge restores the prior state exactly. The registry itself is append-only, so identifier history is never lost.", "key_points": ["Canonical ID lookup first; scoring only when identifiers are absent.", "Fixed weight table and thresholds — no judgment-call matching.", "The middle band is identity-uncertain: linked, excluded, waiting — never forced.", "Merges are reversible link records; the registry is append-only."], "requirements": "The canonical identifier registry; the fixed weight table; merge/unmerge link records.", "standards": "Forced identity decisions prohibited. All merges reversible and evidenced.", "citations": ["Signature canonical identity registry (Signature-labeled)", "Record linkage weight tables (Fellegi-Sunter, public reference)"]}}, {"topic": "Signature Record Fingerprinting", "cat": "verification-procedures", "rank": 1, "tier": "Foundations", "name": "record-fingerprinting", "desc": "A Signature record fingerprint is a deterministic hash over a claim's canonical form — the same claim always produces the same fingerprint, and any alteration produces a different one. Fingerprints make duplicate detection, echo detection, and ledger integrity all mechanical. This record defines the canonicalization rules (field order, whitespace, encoding, number formatting) that the fingerprint covers, and the three uses: dedup (same fingerprint = same record), tamper detection (fingerprint mismatch = altered record), and cross-system claim matching without sharing full record contents.", "body": {"how_it_works": "Canonicalize the claim first: fields in fixed order, Unicode normalized (NFC), whitespace collapsed, numbers in a fixed decimal representation, dates in ISO 8601 — the canonicalization rules are versioned (fingerprint v1.0). Hash the canonical bytes with the specified algorithm to produce the fingerprint. For duplicate detection, compare fingerprints: exact match means the same record, and near-duplicates are found by fingerprinting normalized variants. For tamper detection, re-fingerprint on read and compare with the stored fingerprint; any mismatch triggers the integrity incident procedure. For cross-system matching, exchange fingerprints rather than full records: matching fingerprints prove shared claims without exposing record contents, which matters when records carry access restrictions. Fingerprint version changes are handled by dual-fingerprinting during transitions — old and new fingerprints stored side by side until migration completes.", "key_points": ["Canonicalize before hashing: order, encoding, numbers, dates — all fixed.", "Same fingerprint = same record; mismatch on read = tamper incident.", "Fingerprint exchange enables claim matching without sharing contents.", "Version transitions use dual fingerprinting until migration completes."], "requirements": "Versioned canonicalization rules; the hash algorithm specification; dual-fingerprint transition support.", "standards": "Fingerprints version-stamped. Tamper mismatches trigger the integrity incident procedure.", "citations": ["Content hashing practice (public reference)", "Canonicalization in digital signatures (public reference)"]}}, {"topic": "Provenance-Weighted Resolution", "cat": "provenance-weighting", "rank": 2, "tier": "Compounded", "name": "provenance-weighted-resolution", "desc": "Provenance-weighted resolution is the core Signature reconciliation method: each claim's support is weighted by the verified completeness of its provenance chain, and the claim with the greatest provenance-weighted support wins. Unlike raw vote-counting, it cannot be gamed by echoes — copies share one chain and contribute once. This record gives the weighting formula, the chain-completeness score, the echo-collapse rule, and the margin reporting standard. It is the default Signature method for source-level conflicts.", "body": {"how_it_works": "Score each claim's provenance chain for completeness: every verified link contributes, with weights by link type (direct observation links weigh most, transmission links least), producing a chain score between 0 and 1. Collapse echoes first: claims sharing a chain ancestor above the echo threshold are merged into a single claim position with the ancestor's chain — the copies add corroboration detail but no additional weight. Then compute each surviving claim's support as the sum of chain scores of its independent chains; the winner is the claim with the highest support, and the margin is the support ratio. Report the full computation: chains, scores, echo collapses, and the ratio — the verdict is checkable arithmetic, not authority. When the margin falls below the decisive threshold (2:1), the output is a leaning with the computation attached, and the conflict stays open in the ledger for future evidence.", "key_points": ["Weight = verified chain completeness, not source count.", "Echo collapse before weighting: shared ancestors contribute once.", "The verdict is checkable arithmetic: chains, scores, collapses, ratio.", "Below 2:1 margin = leaning, conflict stays open."], "requirements": "Chain-completeness scoring; the echo threshold and collapse rule; the margin threshold policy.", "standards": "Full computation reported with every verdict. Echo collapse mandatory before weighting.", "citations": ["Signature provenance weighting method v1.0 (Signature-labeled)", "Data fusion weighting literature (public reference)"]}}, {"topic": "The Deterministic Reconciliation Procedure", "cat": "deterministic-reconciliation", "rank": 2, "tier": "Compounded", "name": "deterministic-reconciliation", "desc": "The deterministic reconciliation procedure is the Signature seven-step method that takes a conflict report and produces a verdict with zero analyst discretion in the mechanics: identify, chain-verify, echo-collapse, weight, tie-break, verdict, and ledger-commit. Each step is fixed, ordered, and versioned; the analyst supplies evidence and the procedure supplies the outcome. This record is the procedure specification v1.0 with each step's inputs, operations, and outputs. Run it twice on the same evidence and get the same verdict — that is the whole point.", "body": {"how_it_works": "Step 1, identify: run deterministic conflict identification (procedure v1.0) to produce the version-stamped conflict report. Step 2, chain-verify: build or retrieve the provenance chain for each claim and run the integrity check; claims failing integrity are marked no-standing. Step 3, echo-collapse: map echo clusters by chain ancestry and collapse them to single positions. Step 4, weight: compute provenance-weighted support per surviving claim. Step 5, tie-break: if the margin is below the decisive threshold, apply the fixed tie-break order (newer verified observation beats older; direct beats indirect; complete chain beats gapped chain) — each tie-break is a rule, not a judgment. Step 6, verdict: write the verdict record with outcome, margin, reasons, and dissent. Step 7, ledger-commit: append the verdict to the evidence ledger with all inputs referenced by hash. The procedure version is stamped on the verdict; re-running with new evidence is a new verdict, never an edit.", "key_points": ["Seven fixed steps: identify, chain-verify, echo-collapse, weight, tie-break, verdict, ledger-commit.", "Zero analyst discretion in mechanics; analysts supply evidence, the procedure decides.", "Tie-breaks are fixed rules in fixed order — not judgment calls.", "Same evidence twice = same verdict; new evidence = new verdict."], "requirements": "All seven step procedures at their pinned versions; the tie-break order table; ledger-commit access.", "standards": "Procedure version stamped on every verdict. Steps may not be reordered or skipped.", "citations": ["Signature deterministic reconciliation v1.0 (Signature-labeled)"]}}, {"topic": "Signature Verification Procedures: The Three Passes", "cat": "verification-procedures", "rank": 2, "tier": "Compounded", "name": "three-pass-verification", "desc": "Every Signature claim that enters a conflict undergoes three verification passes: the integrity pass (is the record intact and authentic?), the provenance pass (is the chain complete and verified?), and the substance pass (does the claim survive independent checking?). A claim must pass all three to earn full standing; failing any pass caps its standing accordingly. This record details each pass's checks and the standing levels. The three passes are why Signature verdicts can state exactly how much trust each claim earned and why.", "body": {"how_it_works": "Pass one, integrity: re-fingerprint the record and compare with its stored fingerprint; verify any signatures or seals; confirm the record is the version it claims to be (not a draft, not a superseded copy presented as current). Failure here is disqualifying — an altered record has no standing until re-sourced. Pass two, provenance: build the chain, run the integrity check, and score completeness; gaps cap standing at the verified portion. Pass three, substance: check the claim against independent sources (triangulation), against known constraints (does it violate established facts?), and against its own source's track record on this fact class. Each pass produces a pass report with findings; the three reports combine into the standing determination: full (all passes clean), qualified (minor gaps noted), or contested (material failures). Verdicts cite the pass reports, so \"why did this claim win\" always has a three-pass answer.", "key_points": ["Three passes: integrity, provenance, substance — all three required for full standing.", "Integrity failure disqualifies; provenance gaps cap standing; substance failures contest.", "Each pass produces a report; verdicts cite all three.", "Standing levels: full, qualified, contested — with the reasons attached."], "requirements": "Fingerprint/signature checking; chain verification; independent-source access for substance checks.", "standards": "No claim reaches reconciliation without three pass reports. Standing levels used consistently.", "citations": ["Signature three-pass verification (Signature-labeled)", "Verification levels in auditing practice (public reference)"]}}, {"topic": "Deterministic Tie-Breaks", "cat": "deterministic-reconciliation", "rank": 2, "tier": "Compounded", "name": "deterministic-tie-breaks", "desc": "When weighted support cannot separate two claims, Signature resolution does not shrug — it applies the fixed tie-break order. Tie-breaks are deterministic rules, published in advance, applied in sequence until one claim prevails or the sequence is exhausted (which yields a structured leaning, not a coin flip). This record lists the tie-break order v1.0 with each rule's justification: newer verified observation, direct over indirect, complete chain over gapped, corroborated over solo, and finally the standing rule — when all else is equal, the conflict remains open.", "body": {"how_it_works": "Apply the tie-breaks strictly in order, stopping at the first rule that separates the claims. Rule 1, newer verified observation: the more recently observed claim wins, because the world changes and newer observation is fresher evidence — but only if the newer observation itself passed verification. Rule 2, direct over indirect: a direct observation beats a reported one at equal weight. Rule 3, complete chain over gapped: the claim with the more complete verified provenance wins. Rule 4, corroborated over solo: a claim with independent corroboration beats an uncorroborated one. Rule 5, the standing rule: if all four rules fail to separate the claims, no tie-break is forced — the verdict is a structured leaning documenting the tie, and the conflict stays open in the ledger. Every applied tie-break is named in the verdict with the rule number, so the tie-break path is fully auditable.", "key_points": ["Fixed order, published in advance: newer-verified, direct, complete-chain, corroborated.", "First separating rule wins; the path is named in the verdict.", "Rule 5: unbreakable ties stay open as structured leanings — never coin flips.", "Tie-breaks apply only after weighting; they never replace it."], "requirements": "The tie-break order table v1.0; verification status for recency claims; the open-conflict holding format.", "standards": "Tie-break path named rule-by-rule in every verdict. Forced tie-breaks prohibited.", "citations": ["Signature tie-break order v1.0 (Signature-labeled)"]}}, {"topic": "Signature Witness Weighting", "cat": "provenance-weighting", "rank": 2, "tier": "Compounded", "name": "signature-witness-weighting", "desc": "When human witnesses conflict, Signature weighting treats each witness as a sensor with a calibration record: past accuracy on similar observations, observation conditions, and corroboration history combine into a witness weight. This record gives the witness calibration method, the conditions discount table (distance, lighting, delay, stress), and the combination rule. The method is deliberately symmetric — it weights all witnesses by the same rules, with no credibility judgments beyond the calibration data.", "body": {"how_it_works": "Build each witness's calibration record: verified past observations in the same domain, scored for accuracy, forming the base weight. Apply the conditions discount from the fixed table: each adverse condition (poor lighting, long distance, long delay before statement, high stress) multiplies the weight by its discount factor — the factors are published and identical for all witnesses. Add the corroboration adjustment: witnesses whose past statements were independently corroborated gain a small premium; witnesses with past contradictions carry a small penalty — both computed from records, not impressions. Combine witness weights with the standard provenance weighting: each witness's claim gets support equal to its calibrated weight, echoes (witnesses repeating each other or a common source) collapse to one position. The output names every witness's weight components, so the weighting is inspectable rather than mysterious.", "key_points": ["Witnesses are calibrated sensors: base weight from verified past accuracy.", "Conditions discounts are fixed, published, and symmetric across witnesses.", "Corroboration history adjusts weight from records, not impressions.", "Every weight component is named in the output — inspectable, not mysterious."], "requirements": "Witness calibration records; the conditions discount table; corroboration history data.", "standards": "Same discount table for all witnesses. Weight components disclosed in every verdict.", "citations": ["Signature witness calibration method (Signature-labeled)", "Eyewitness calibration research (public reference)"]}}, {"topic": "Canonical Fact Election", "cat": "arbitration", "rank": 2, "tier": "Compounded", "name": "canonical-fact-election", "desc": "After reconciliation, exactly one claim becomes the canonical fact — the version the system serves, cites, and builds on — while the others remain in history with their statuses. Canonical fact election is the formal step that promotes the verdict's winner to canonical status, with the election record stating what was elected, why, when, and what happens if it is later dethroned. This record defines the election procedure, the canonical record format, and the dethronement protocol. One canonical fact at a time, with the full history behind it.", "body": {"how_it_works": "The election takes the reconciliation verdict as input and verifies its completeness (all seven steps, version stamps, margin above threshold or documented leaning). If valid, it writes the canonical record: the winning claim's full text, its fingerprint, the verdict reference, the election timestamp, and the supersession links to the claims it replaces. The canonical record is what all downstream systems read — one source of current truth. Dethronement follows the same path in reverse: new evidence triggers re-reconciliation, and if the new verdict differs, a new canonical record is elected with a supersedes link to the old one — the old canonical fact is never edited, only superseded. Elections are announced in the ledger with the election record, so any consumer can verify what is canonical as of any date. Emergency dethronement (for retracted or dangerous claims) follows an expedited path with mandatory post-hoc review.", "key_points": ["One canonical fact at a time; election is a formal, recorded step.", "The canonical record carries claim, fingerprint, verdict reference, and timestamp.", "Dethronement = new election with supersedes link; old canonicals are never edited.", "Emergency dethronement allowed with mandatory post-hoc review."], "requirements": "Complete reconciliation verdicts; the canonical record schema; dethronement protocol; ledger announcement.", "standards": "No canonical fact without a complete verdict. Dethronements link predecessors.", "citations": ["Signature canonical election procedure (Signature-labeled)", "Single-source-of-truth architecture (public reference)"]}}, {"topic": "Signature Audit Certificates", "cat": "verification-procedures", "rank": 2, "tier": "Compounded", "name": "audit-certificates", "desc": "A Signature audit certificate is the portable proof that a claim survived the full verification and reconciliation process: it bundles the claim, its fingerprint, the three pass reports, the verdict, and the ledger references into one signed package. Anyone holding the certificate can verify the claim's standing without re-running the whole procedure. This record defines the certificate format, the signing process, and the verification protocol. Certificates are how Signature trust travels between systems.", "body": {"how_it_works": "Assemble the certificate from the ledger: the canonical claim text, its fingerprint, the three pass reports (integrity, provenance, substance), the reconciliation verdict with margin and method, and the ledger entry hashes anchoring each component. Sign the package with the issuing authority's key and timestamp it; the signature covers the entire bundle, so any tampering invalidates the certificate. Verification is mechanical: check the signature, re-verify the ledger anchors (do the referenced entries exist with matching hashes?), and confirm the certificate has not been superseded by querying the ledger for newer verdicts on the same claim. Certificates carry expiry or re-verification intervals for time-sensitive claims — a 2024 certificate for a price fact is not valid in 2026 without refresh. Revoked certificates are published on the revocation list; verification must check it.", "key_points": ["The certificate bundles claim, passes, verdict, and ledger anchors — one signed package.", "Verification is mechanical: signature, anchors, supersession check, revocation check.", "Time-sensitive claims carry re-verification intervals.", "Trust travels with the certificate; re-running the procedure is optional."], "requirements": "The certificate schema; signing keys and timestamping; the revocation list; ledger query access.", "standards": "Certificates must anchor to ledger entries by hash. Revocation checks mandatory on verification.", "citations": ["Signature audit certificate format v1.0 (Signature-labeled)", "Digital certificate concepts (public reference)"]}}, {"topic": "Time-Anchored Fact Resolution", "cat": "lineage-resolution", "rank": 3, "tier": "Compounded", "name": "time-anchored-resolution", "desc": "Signature time-anchored resolution treats time as part of a fact's identity: the resolved output is always a set of (claim, valid-interval) pairs, never a bare winner. When sources conflict across time, the procedure anchors each claim to its verified valid interval and merges them into a timeline; genuine contradictions are only those whose intervals overlap. This record gives the anchoring procedure, the interval-merge rules, and the overlap test. It is the Signature answer to the fact that most \"contradictions\" are just history.", "body": {"how_it_works": "For each claim, establish its valid interval from the provenance chain: the observation timestamp gives the interval's core, and corroborating records extend or bound it — intervals are evidenced, not guessed. Run the overlap test on every claim pair: non-overlapping intervals mean no conflict, and both claims are preserved in the timeline with their intervals. For overlapping intervals, the conflict is genuine and enters provenance-weighted resolution restricted to the overlap period — claims may win different sub-intervals, producing a segmented timeline. Merge the results into the canonical timeline: a sequence of (interval, canonical claim) segments covering the full span, each segment citing its verdict. Gaps — periods with no verified claim — are marked unknown rather than interpolated. The timeline is the canonical fact for time-dependent attributes, and it updates by segment supersession as new evidence arrives.", "key_points": ["Time is part of fact identity: outputs are (claim, interval) pairs.", "Non-overlapping intervals = no conflict; preserve both in the timeline.", "Overlapping intervals = genuine conflict; resolve per segment.", "Gaps are marked unknown — never interpolated."], "requirements": "Evidenced valid intervals per claim; the overlap test; the timeline merge rules.", "standards": "Bare-winner outputs prohibited for time-dependent facts. Unknown gaps marked explicitly.", "citations": ["Signature time-anchoring method (Signature-labeled)", "Bitemporal data modeling (public reference)"]}}, {"topic": "Signature Cross-Verification Protocol", "cat": "verification-procedures", "rank": 3, "tier": "Compounded", "name": "cross-verification", "desc": "Signature cross-verification requires every high-stakes claim to survive checking by two independent verification paths before it can win a conflict: the paths must differ in method, in personnel or system, and in source material. This record defines path independence, the cross-verification workflow, and the handling of path disagreement (which triggers escalation, not averaging). Cross-verification is the reason Signature verdicts can claim robustness rather than mere procedure-following.", "body": {"how_it_works": "Design two verification paths that are independent on all three axes: different methods (e.g., document analysis vs instrumental measurement), different verifiers (different analysts or systems, no shared supervision on this case), and different source material (no shared upstream sources — the independence check from echo detection applies). Run both paths to completion and compare: agreement at the required confidence confirms the claim; disagreement triggers the escalation protocol — a third path is designed specifically around the disagreement point, and the conflict is re-analyzed rather than averaged. Document the path design, the independence justification per axis, and both paths' findings in the verification record. Single-path verification is permitted only below the high-stakes threshold, and the threshold itself is published. Cross-verification findings feed the witness/source calibration records, improving future weighting.", "key_points": ["Two paths, independent on method, personnel, and source material.", "Path disagreement triggers escalation with a third path — never averaging.", "Independence justified per axis in the verification record.", "Findings feed calibration records for future weighting."], "requirements": "The path-independence criteria; the escalation protocol; the high-stakes threshold definition.", "standards": "High-stakes claims require two-path verification. Averaging disagreeing paths prohibited.", "citations": ["Signature cross-verification protocol (Signature-labeled)", "Independent verification in safety engineering (public reference)"]}}, {"topic": "The Contradiction Register", "cat": "conflict-ledger", "rank": 3, "tier": "Compounded", "name": "contradiction-register", "desc": "The Signature contradiction register is the single index of every known contradiction: open, resolved, or abstained — each with its claims, status, verdict reference, and history. It is the operational view over the evidence ledger, built for the question \"what contradictions do we currently have?\" This record defines the register schema, the status lifecycle (detected → in-procedure → resolved → monitored; or abstained), and the review rhythms. No contradiction exists officially until it is registered; no resolution counts until the register reflects it.", "body": {"how_it_works": "Register each detected contradiction with a unique register ID, the conflicting claim fingerprints, the conflict report reference, detection timestamp, and initial status detected. As the reconciliation procedure runs, update the status through in-procedure with the current step; on verdict, set resolved with the verdict reference, or abstained with the abstention record. Resolved entries enter monitored status on a review schedule matched to the fact's half-life — time-sensitive resolutions get re-checked, because the world changes. The register supports the operational queries: open contradictions by age (stale investigations surface), by fact class (systematic problem areas emerge), and by source (a source appearing in many contradictions is investigated). Registration is mandatory at detection: an unregistered contradiction is a procedure violation, and the register's completeness is itself audited.", "key_points": ["One register, every contradiction: open, resolved, abstained — all indexed.", "Status lifecycle: detected → in-procedure → resolved → monitored (or abstained).", "Resolved entries are monitored on the fact's half-life schedule.", "Unregistered contradictions are procedure violations."], "requirements": "The register schema; status lifecycle enforcement; review schedules; completeness audits.", "standards": "Registration mandatory at detection. Register completeness audited.", "citations": ["Signature contradiction register spec (Signature-labeled)", "Issue-tracker lifecycle design (public reference)"]}}, {"topic": "Signature Reconciliation Contracts", "cat": "deterministic-reconciliation", "rank": 3, "tier": "Compounded", "name": "reconciliation-contracts", "desc": "A Signature reconciliation contract is the pre-commitment that governs a specific conflict's resolution: which procedure version runs, which tie-breaks apply, what counts as decisive, who decides, and what happens with the output. Contracts are agreed before the evidence is weighed, which prevents moving the goalposts mid-procedure. This record gives the contract template and the execution rules. The contract is the Signature answer to outcome-driven reasoning.", "body": {"how_it_works": "Draft the contract at conflict registration: name the procedure version (e.g., deterministic reconciliation v1.0), the applicable tie-break order, the decisive-margin threshold, the decider's identity and authority, the evidence cutoff rules (what arrives late and how it is handled), and the output commitments (verdict format, ledger commit, announcement). All parties to the conflict — or the governing authority for unilateral cases — sign the contract before step 1 of the procedure runs. Execution follows the contract exactly: mid-procedure changes require a contract amendment, signed and ledger-recorded with the reason — and amendments driven by emerging evidence are themselves evidence of nothing except process. The completed contract, with the verdict attached, is archived as the resolution's governing document. Post-hoc review checks contract compliance as the first audit step.", "key_points": ["The contract is signed before evidence is weighed — no moving goalposts.", "Names procedure version, tie-breaks, margins, decider, evidence rules, outputs.", "Mid-procedure changes need signed, ledger-recorded amendments.", "Post-hoc audit starts with contract compliance."], "requirements": "The contract template; signing authority rules; the amendment procedure.", "standards": "No reconciliation without a signed contract. Amendments ledger-recorded with reasons.", "citations": ["Signature reconciliation contract template (Signature-labeled)", "Pre-registration in scientific research (public reference)"]}}, {"topic": "Deterministic Snapshot Truth", "cat": "lineage-resolution", "rank": 3, "tier": "Compounded", "name": "deterministic-snapshot", "desc": "A Signature snapshot is the complete, hash-anchored state of what the system held true at an exact moment — every canonical fact, every verdict, every ledger head hash, frozen and fingerprintable. Snapshots make \"what did we believe on March 3rd\" a mechanical query instead of an archaeological dig, and they let two systems prove they held the same beliefs. This record defines the snapshot format, the snapshot schedule, and the cross-system comparison protocol. Snapshots are the unit of historical truth in the Signature system.", "body": {"how_it_works": "At each scheduled snapshot point (and on demand before major decisions), compute the snapshot: the full set of canonical facts with fingerprints, the ledger head hash, the contradiction register state, and the snapshot timestamp — then fingerprint the entire snapshot. Store snapshots immutably; each snapshot references its predecessor, forming a snapshot chain parallel to the ledger. The time-travel query is answered from snapshots: find the snapshot at or before the target date and read its canonical facts directly. Cross-system comparison exchanges snapshot fingerprints: matching fingerprints prove identical belief states without exchanging any fact contents. Snapshot verification re-computes a past snapshot from the ledger and compares fingerprints — any mismatch is an integrity incident. The schedule balances cost and granularity: daily for active systems, with on-demand snapshots before high-stakes decisions.", "key_points": ["Snapshots freeze the full belief state: facts, verdicts, ledger head — all fingerprinted.", "Time-travel queries read snapshots directly — no archaeology.", "Fingerprint exchange proves shared beliefs without sharing contents.", "Re-computation from the ledger verifies snapshots; mismatches are incidents."], "requirements": "The snapshot schema; snapshot schedule; immutable snapshot storage; re-computation verification.", "standards": "Snapshots immutable and chained. Verification by ledger re-computation.", "citations": ["Signature snapshot specification (Signature-labeled)", "Database snapshot concepts (public reference)"]}}, {"topic": "Provenance-Weighted Bayesian Resolution", "cat": "provenance-weighting", "rank": 4, "tier": "Advanced", "name": "provenance-weighted-bayes", "desc": "This record formalizes provenance-weighted resolution in Bayesian terms: provenance chain completeness becomes the likelihood function, and the Signature weighting formula becomes a special case of Bayesian updating with provenance-calibrated likelihoods. The formalization matters because it connects the Signature method to the broader evidence-combination literature and exposes exactly where judgment enters (the priors) versus where the procedure rules (the likelihoods). This record gives the formal mapping, the calibration requirements that keep it honest, and the sensitivity analysis that separates robust verdicts from fragile ones.", "body": {"how_it_works": "Map each claim's provenance chain score to a likelihood: the probability that a chain of this completeness would support the claim if the claim were true versus false — calibrated from the ledger's historical record of chain scores against later-verified outcomes. Combine with the prior (neutral unless a base rate is justified and documented) via Bayes' rule across the independent chains. The Signature weighting formula emerges as the special case with uniform priors and the standard chain-score likelihood mapping — which is why the formalization validates rather than replaces the standard method. Run sensitivity analysis on the priors and the likelihood calibration: verdicts stable across the plausible range are robust; verdicts that flip are reported as fragile with the flipping conditions named. The Bayesian framing also handles partial evidence naturally: incomplete chains contribute partial likelihoods instead of being discarded. All calibration data comes from the ledger's own history — the system learns its likelihoods from its track record.", "key_points": ["Chain completeness becomes calibrated likelihoods; priors stay explicit and justified.", "The standard Signature formula is the uniform-prior special case — validated, not replaced.", "Sensitivity analysis separates robust verdicts from fragile ones.", "Likelihoods calibrated from the ledger's own history — the system learns from its track record."], "requirements": "Historical chain-score vs outcome data; justified priors; sensitivity analysis procedure.", "standards": "Priors documented with justification. Fragile verdicts labeled with flipping conditions.", "citations": ["Signature Bayesian formalization note (Signature-labeled)", "Bayesian data fusion literature (public reference)"]}}, {"topic": "Echo-Chamber Detection by Signature Lineage", "cat": "provenance-weighting", "rank": 4, "tier": "Advanced", "name": "lineage-echo-detection", "desc": "Signature lineage makes echo detection mechanical: because every claim carries its hash-linked provenance chain, finding the common ancestor of ten agreeing sources is a graph operation, not an investigation. This record gives the lineage-graph method: build the ancestry graph from the chains, find convergence points, measure the independence of the surviving positions, and apply the collapse. It also covers the hard cases: laundered echoes (chains rewritten to hide the common source) and genuinely independent convergence (two chains that truly observed separately).", "body": {"how_it_works": "Collect the provenance chains of all claims on each side and build the ancestry graph: nodes are chain links, edges are predecessor relations. Find convergence: positions whose chains share an ancestor above the echo threshold collapse to one position — the graph makes the shared ancestry visible and checkable. Then test the survivors for genuine independence: do their chains show separate observations (different observers, different times, different methods), or do they merely diverge cosmetically? Laundered echoes — chains rewritten to hide copying — are caught by content fingerprinting: identical distinctive errors or phrasings across \"independent\" chains trigger the forgery investigation. Genuinely independent convergence (separate chains, same conclusion) is the strongest possible support and is weighted accordingly — independence verified by lineage is worth more than independence assumed. The ancestry graph is archived with the verdict as the echo evidence.", "key_points": ["Hash-linked chains make echo detection a graph operation.", "Convergence above threshold collapses; survivors tested for genuine independence.", "Laundered echoes caught by content fingerprinting across chains.", "Verified independent convergence is the strongest support signal."], "requirements": "Complete provenance chains for all claims; the ancestry graph builder; the echo threshold; content fingerprinting.", "standards": "Ancestry graphs archived with verdicts. Laundering findings trigger forgery investigation.", "citations": ["Signature lineage graph method (Signature-labeled)", "Provenance graph analysis (public reference)"]}}, {"topic": "Multi-Agent Signature Arbitration", "cat": "arbitration", "rank": 4, "tier": "Advanced", "name": "multi-agent-arbitration", "desc": "For the hardest conflicts, Signature arbitration convenes multiple independent reconciler agents — each running the deterministic procedure on the same evidence but with independent chain verification — and reconciles their verdicts. This record defines the arbitration panel protocol: agent independence requirements, the verdict-comparison procedure, and the escalation ladder when agents disagree. Arbitration does not replace the deterministic procedure; it stress-tests it, and agent disagreement is treated as information about the conflict's difficulty, not as noise.", "body": {"how_it_works": "Seat a panel of three or more reconciler agents with enforced independence: different implementations or configurations, no shared chain-verification work, no communication during the procedure. Each agent independently runs the full deterministic reconciliation on the same conflict and produces a signed verdict with its complete computation. Compare the verdicts: unanimous agreement confirms the resolution at the highest confidence; majority agreement with a dissenting agent triggers the dissent analysis — the dissent's computation is examined step by step to find where it diverged, and the divergence point is investigated as potential evidence the majority missed. Persistent agent disagreement after dissent analysis escalates to the standing rule: the conflict is genuinely hard, the output is the agent-verdict set with the disagreement mapped, and the contradiction register holds it open. Panel proceedings are ledger-recorded in full.", "key_points": ["Three+ independent agents, same evidence, no communication during procedure.", "Unanimity = highest confidence; dissent triggers step-by-step divergence analysis.", "Persistent disagreement = genuinely hard conflict; output the mapped disagreement.", "Full panel proceedings ledger-recorded."], "requirements": "Independent reconciler agents; the verdict-comparison procedure; dissent analysis protocol; escalation rules.", "standards": "Agent independence enforced and documented. Dissent analyses archived.", "citations": ["Signature arbitration panel protocol (Signature-labeled)", "Ensemble and adjudication methods (public reference)"]}}, {"topic": "The Signature Consistency Theorem", "cat": "deterministic-reconciliation", "rank": 4, "tier": "Advanced", "name": "consistency-theorem", "desc": "The Signature consistency theorem states the guarantee precisely: given the same evidence set, the same procedure version, and the same contract, the deterministic reconciliation procedure always produces the same verdict — and any two systems can verify this by exchanging verdict fingerprints. This record states the theorem, sketches its proof (determinism of each step composes into determinism of the whole), lists the exact preconditions, and explains what the theorem does not promise (it does not promise truth — only reproducibility; truth comes from the evidence, via the procedure). The theorem is the formal foundation of Signature trust claims.", "body": {"how_it_works": "The proof proceeds by step composition: identification is deterministic by its fixed rules; chain verification is deterministic given the chains; echo collapse is deterministic given the ancestry graph and threshold; weighting is arithmetic; tie-breaks are ordered rules; verdict writing is templated; ledger commit is append-only. Each step's output is a pure function of its inputs, so the pipeline is a pure function of (evidence, procedure version, contract) — identical inputs, identical verdict, by construction. Verification between systems is fingerprint comparison: both systems publish the verdict fingerprint (hash of the canonical verdict record); matching fingerprints prove identical processing without sharing evidence. The preconditions are strict and checkable: evidence sets must be fingerprint-identical, procedure versions must match, contracts must match. When fingerprints differ, the preconditions are diffed to find the divergence — the theorem turns disagreements into diagnosable diffs.", "key_points": ["Same evidence + same procedure version + same contract = same verdict, always.", "Determinism composes: each step is a pure function of its inputs.", "Cross-system verification by verdict fingerprint comparison.", "The theorem promises reproducibility, not truth — truth comes via evidence."], "requirements": "Pinned procedure versions; the contract; fingerprint-identical evidence sets; verdict fingerprinting.", "standards": "Trust claims cite the theorem with its preconditions. Fingerprint diffs diagnose divergences.", "citations": ["Signature consistency theorem statement (Signature-labeled)", "Deterministic computation theory (public reference)"]}}, {"topic": "Deterministic Repair of Contradictory Graphs", "cat": "deterministic-reconciliation", "rank": 4, "tier": "Advanced", "name": "graph-repair", "desc": "When contradictions live in a knowledge graph, Signature repair restores consistency deterministically: constraints are the law, repairs are ranked by fixed rules, and the winning repair is a pure function of the graph, the constraints, and the provenance scores. This record gives the repair procedure: violation detection, candidate generation, the fixed ranking order (minimality, then provenance priority, then recency, then the deterministic final tie-break), and the repair transaction format. Two systems repairing the same graph produce the same repaired graph — the consistency theorem applied to graphs.", "body": {"how_it_works": "Encode constraints as checkable rules and run violation detection to enumerate every violated constraint with its conflicting assertion set. Generate all candidate repairs within the minimality bound: each candidate is a set of assertion-level changes (retract, correct, time-index) that clears all violations. Rank candidates with the fixed order: fewest changes first; ties broken by provenance priority (candidates changing lower-scored assertions rank higher); remaining ties by recency (keep newer verified assertions); final ties by the deterministic rule (lowest assertion fingerprint sorts first) — the last rule exists so the ranking is total and the winner is unique. Apply the winner as a single repair transaction recording the violations, all candidates, the ranking with scores, and the applied changes. Re-run violation detection to confirm consistency, then commit the transaction to the ledger. The repaired graph's fingerprint is published for cross-system verification.", "key_points": ["Constraints are law; violations enumerate the repair candidates.", "Fixed ranking: minimality → provenance priority → recency → fingerprint order.", "The final tie-break guarantees a unique winner — determinism preserved.", "Repair transactions record violations, candidates, ranking, and changes."], "requirements": "Checkable constraint set; assertion provenance scores; the ranking order pinned; transaction format.", "standards": "Ranking order immutable within a procedure version. All candidates archived, not just the winner.", "citations": ["Signature graph repair procedure (Signature-labeled)", "Consistent query answering / database repair (public reference)"]}}, {"topic": "Signature Provenance Decay Functions", "cat": "provenance-weighting", "rank": 4, "tier": "Advanced", "name": "provenance-decay", "desc": "Provenance weight decays with time and with distance: a ten-year-old observation weighs less than a fresh one, and a fifth-hand report weighs less than a direct one — but the decay follows fixed functions, not gut feeling. This record defines the Signature decay functions: the time-decay curve per fact class (tied to the half-life table) and the transmission-decay per chain link (each hand the claim passes through multiplies weight by the link factor). Decay functions keep old, long-chain claims from outvoting fresh, direct ones, while preserving them in history.", "body": {"how_it_works": "Apply time decay first: each claim's base chain score is multiplied by the time-decay factor from its fact class's curve — the curves are published per class (fast-decay classes like prices fall steeply; slow-decay classes like founding dates fall gently), and the decay is computed from the observation timestamp, not the recording timestamp. Then apply transmission decay: walk the provenance chain and multiply by the link factor at each transmission link (observation and recording links are not discounted; each subsequent hand multiplies by the fixed factor, e.g., 0.9). The decayed score is the claim's effective weight in reconciliation. Decay never deletes: a fully decayed claim remains in the ledger with its history, contributing context but not votes. The decay parameters are versioned with the procedure, and verdicts report the decayed weights with the curves cited — the aging of evidence is arithmetic, not rhetoric.", "key_points": ["Time decay per fact class from published half-life curves.", "Transmission decay per chain link: each hand multiplies by the fixed factor.", "Decay reduces weight, never deletes — history is preserved.", "Decayed weights reported with curves cited; aging is arithmetic."], "requirements": "Half-life curves per fact class; the transmission link factor; versioned decay parameters.", "standards": "Decay functions versioned with the procedure. Verdicts report decayed weights and curves.", "citations": ["Signature decay functions v1.0 (Signature-labeled)", "Temporal decay in information retrieval (public reference)"]}}, {"topic": "Conflict-Free Merged Records", "cat": "arbitration", "rank": 4, "tier": "Advanced", "name": "conflict-free-merge", "desc": "Some conflicts should never happen twice: when two records describe the same entity, Signature merge produces a single conflict-free merged record that both sides' systems can share and extend without re-creating the contradiction. This record defines the merge format (field-level provenance: every field cites its source claim), the merge procedure (reconcile field by field with the deterministic procedure), and the extension protocol (new claims about the entity merge into the record through the same procedure). The merged record is a living document with a complete ancestry.", "body": {"how_it_works": "Align the conflicting records field by field using the canonical schema; each field becomes a mini-conflict resolved by the deterministic reconciliation procedure at field scope. Assemble the merged record: every field carries its winning claim, the claim's fingerprint, the field-level verdict reference, and the provenance chain — the record is a mosaic with a complete manifest. Fields where reconciliation abstained are marked disputed-with-status rather than dropped, so the merge never hides an open conflict. Publish the merged record with its fingerprint; systems adopting it verify the fingerprint and inherit the entire resolution history. Extension follows the same path: a new claim about the entity is field-aligned, reconciled against the current field value, and merged — the record grows without ever re-creating resolved contradictions. Merge lineage is itself ledger-recorded, so the merged record's ancestry is fully traceable.", "key_points": ["Field-level reconciliation: each field resolved by the deterministic procedure.", "Every field cites its source claim: the merge is a mosaic with a manifest.", "Abstained fields marked disputed — merges never hide open conflicts.", "Extension uses the same procedure; resolved contradictions never recur."], "requirements": "The canonical schema for field alignment; field-scope reconciliation; the merge manifest format.", "standards": "Merges carry complete field manifests. Disputed fields marked, never dropped.", "citations": ["Signature merge procedure (Signature-labeled)", "CRDT / conflict-free replicated data concepts (public reference)"]}}, {"topic": "Signature Abstention Protocol", "cat": "arbitration", "rank": 5, "tier": "Advanced", "name": "signature-abstention", "desc": "When the Signature procedure cannot resolve a conflict — symmetric evidence, unbreakable ties, missing keystones — it abstains, and it abstains in a structured, useful way. The abstention protocol defines exactly what is produced instead of a verdict: the competing positions with their decayed weights, the precise reason resolution failed, the evidence that would re-open the case, and the monitoring schedule. This record gives the protocol and the re-open triggers. In the Signature system, a structured abstention outranks a forced answer — always.", "body": {"how_it_works": "After the full deterministic procedure yields no decisive verdict (margin below threshold through all tie-breaks, or an impossibility criterion met), the protocol produces the abstention record: the competing claims with their full weight computations, the named failure point (which step, which criterion), the known/unknown inventory, and the re-open triggers specified as concrete evidence conditions (\"a verified observation dated before 2019\" rather than \"more evidence\"). The contradiction register holds the conflict open with status abstained and the monitoring schedule set from the fact's half-life — the case is re-examined when triggers arrive or the schedule fires. If new evidence arrives, re-reconciliation runs as a new procedure instance referencing the abstention; the abstention is never edited. Forced answers are procedure violations: any verdict issued where the protocol required abstention is flagged in audit, and the audit finding names the violated criterion.", "key_points": ["Abstention is structured: positions, weights, failure point, known/unknown, re-open triggers.", "The register holds abstained conflicts open on a monitoring schedule.", "Re-opening runs a new procedure instance; abstentions are never edited.", "Forced answers where abstention was required are audit-flagged violations."], "requirements": "The impossibility criteria; the abstention record format; re-open trigger specification; monitoring schedules.", "standards": "Abstentions are first-class records. Forced-answer violations flagged in audit.", "citations": ["Signature abstention protocol (Signature-labeled)", "Abstention in decision theory (public reference)"]}}, {"topic": "The Signature Truth Assembly Pipeline", "cat": "deterministic-reconciliation", "rank": 5, "tier": "Advanced", "name": "truth-assembly-pipeline", "desc": "The truth assembly pipeline is the production deployment of Signature reconciliation: conflicts stream in from across the system, are routed to procedure instances, and emerge as verdicts, canonical facts, and ledger entries — continuously, deterministically, and auditably. This record specifies the pipeline architecture: the intake router, the procedure workers, the ledger committer, and the monitors. It is how Signature resolution operates at the scale of a million-record system without losing determinism or auditability.", "body": {"how_it_works": "The intake router receives conflict reports, validates their format and procedure-version stamps, and assigns each to a procedure worker with the conflict's contract attached; routing is by content hash, so identical conflicts route identically and duplicate reports collapse. Workers execute the deterministic reconciliation procedure in isolated instances — no shared state between cases, which preserves the purity the consistency theorem requires. Completed verdicts flow to the ledger committer, which appends the verdict, updates the contradiction register, and triggers canonical election where applicable — the committer is the pipeline's only writer, which serializes all state changes. Monitors watch the pipeline's health: procedure-version drift (workers must run the contracted version), verdict latency by conflict class, and the abstention rate (a rising rate signals evidence-quality problems upstream). Backpressure is explicit: when workers saturate, intake queues with priority by stakes rather than silently dropping conflicts.", "key_points": ["Intake router validates and hash-routes; duplicate reports collapse.", "Isolated worker instances preserve the determinism the theorem requires.", "Single ledger committer serializes all state changes.", "Monitors track version drift, latency, and abstention rate; backpressure is explicit."], "requirements": "The router, worker, committer, and monitor components; content-hash routing; priority queueing.", "standards": "Workers run contracted procedure versions only. All state changes through the committer.", "citations": ["Signature pipeline architecture (Signature-labeled)", "Stream processing pipeline design (public reference)"]}}, {"topic": "Lineage-Stamped Reconciliation Records", "cat": "lineage-resolution", "rank": 5, "tier": "Advanced", "name": "lineage-stamped-records", "desc": "Every Signature reconciliation record carries its lineage stamp: the procedure version, the contract reference, the evidence fingerprints, the tie-break path, and the ledger anchors — everything needed to replay the reconciliation exactly. This record defines the lineage stamp format and the replay protocol: given the stamp and the ledger, any party can re-derive the verdict bit-for-bit. Lineage stamps are what make Signature verdicts portable trust — the stamp is the proof, the ledger is the evidence room.", "body": {"how_it_works": "At verdict time, the procedure assembles the lineage stamp: procedure version and step configuration, the signed contract reference, the fingerprint of every evidence item used, the tie-break rules applied in order, the intermediate computations (chain scores, decayed weights, margins), and the ledger entry hashes for the verdict commit. The stamp is itself fingerprinted and stored with the verdict. Replay takes a stamp plus ledger access: re-fetch the evidence by fingerprint, re-run the pinned procedure version with the stamped configuration, and compare the recomputed verdict fingerprint with the stamped one — match means the verdict is exactly reproducible. Stamps travel with verdicts across systems: a receiving system verifies the stamp's internal consistency and spot-checks ledger anchors rather than re-running everything. Stamp verification failures — evidence fingerprints that do not resolve, procedure versions unknown — are integrity incidents, investigated before the verdict is used.", "key_points": ["The stamp captures everything needed to replay: version, contract, evidence, tie-breaks, anchors.", "Replay re-derives the verdict bit-for-bit from stamp plus ledger.", "Stamps make verdicts portable: verify the stamp, spot-check anchors.", "Stamp verification failures are integrity incidents."], "requirements": "The lineage stamp schema; pinned procedure versions; ledger access for replay; stamp fingerprinting.", "standards": "Every verdict carries a complete lineage stamp. Stamps verified before cross-system use.", "citations": ["Signature lineage stamp format v1.0 (Signature-labeled)", "Reproducibility packaging (research compendia, public reference)"]}}, {"topic": "Deterministic Majority with Provenance Tiers", "cat": "provenance-weighting", "rank": 5, "tier": "Advanced", "name": "tiered-majority", "desc": "When many sources weigh in, Signature resolution uses tiered majority: sources are sorted into provenance tiers (direct observers, verified transmitters, distant reporters), and the majority is computed tier by tier from the top down — a lower tier is consulted only when the upper tiers tie or abstain. This record defines the tier structure, the tier-by-tier decision procedure, and the anti-capture rule: no tier's majority can be manufactured by flooding it with echoes, because echo collapse runs before tiering. Tiered majority is the Signature answer to \"but most sources say.\"", "body": {"how_it_works": "Assign every source to a tier by its provenance: tier 1 holds direct observers with complete chains; tier 2 holds verified transmitters (complete chains, no direct observation); tier 3 holds distant reporters (gapped chains, secondary material). Run echo collapse first across all tiers — flooding a tier with copies changes nothing. Then decide top-down: compute the provenance-weighted position within tier 1; if tier 1 reaches a decisive margin, the decision is made and lower tiers are recorded as corroboration only. If tier 1 ties or abstains, tier 2's weighted position breaks it; tier 3 is consulted only if tier 2 also ties. The anti-capture rule is structural: because lower tiers cannot override upper tiers, manufacturing a majority requires capturing the top tier — which requires forging complete provenance chains, the hardest attack. The verdict reports the tier table: each tier's position, weight, and whether it decided or corroborated.", "key_points": ["Tiers by provenance: direct observers, verified transmitters, distant reporters.", "Top-down decision: lower tiers corroborate unless upper tiers tie.", "Echo collapse before tiering: flooding a tier manufactures nothing.", "Verdicts report the full tier table."], "requirements": "The tier definitions; echo collapse; the top-down decision procedure; the tier table report format.", "standards": "Tier assignment by verified provenance only. Lower tiers never override upper tiers.", "citations": ["Signature tiered majority procedure (Signature-labeled)", "Hierarchical evidence grading (GRADE system analogy, public reference)"]}}, {"topic": "Signature Conflict Drills", "cat": "conflict-ledger", "rank": 5, "tier": "Advanced", "name": "conflict-drills", "desc": "Signature operators rehearse conflict resolution the way pilots rehearse emergencies: scheduled drills inject synthetic contradictions into a sandbox ledger, and the team must run the full procedure — identification through ledger commit — against the clock. This record defines the drill program: the contradiction injection library, the scoring rubric (correctness of verdict, completeness of records, time), and the after-action review. Drills are how the procedure stays sharp and how new operators earn their standing.", "body": {"how_it_works": "The drill controller selects contradictions from the injection library — each a synthetic conflict with a known-correct resolution, covering the conflict types, edge cases (echo floods, forged chains, symmetric evidence requiring abstention), and procedure-version changes. The team works the drill in the sandbox: real procedure, real ledger format, synthetic data, with the clock running and the contract signed as in production. Scoring covers three axes: verdict correctness against the known answer, record completeness (every required artifact produced and properly formatted), and time against the class standard. The after-action review examines every deviation: wrong verdicts are traced to the step that failed, slow drills to the bottleneck, and the findings feed procedure clarifications or training. Drill records are kept but clearly marked synthetic — they never mix with the production ledger. Operators must pass the drill battery before handling high-stakes conflicts unsupervised.", "key_points": ["Synthetic contradictions, known answers, sandbox ledger, running clock.", "Scored on verdict correctness, record completeness, and time.", "After-action reviews trace every deviation to its step.", "Drill records marked synthetic; operators certified before high-stakes work."], "requirements": "The injection library; sandbox ledger; scoring rubric; after-action review format; certification standard.", "standards": "Drill data never mixes with production. High-stakes work requires drill certification.", "citations": ["Signature drill program (Signature-labeled)", "Emergency drill methodology (public reference)"]}}, {"topic": "The Immutable Conflict History Chain", "cat": "conflict-ledger", "rank": 5, "tier": "Advanced", "name": "conflict-history-chain", "desc": "The immutable conflict history chain links every contradiction the system has ever processed into a single hash-chained sequence: each entry references its predecessor, so the entire history of conflict and resolution is tamper-evident as one chain. This record defines the chain structure, the entry format, and the verification protocol. The chain is the ultimate audit artifact: it proves not just that each resolution was correct, but that no resolution was ever quietly altered or removed.", "body": {"how_it_works": "Each contradiction, from registration through verdict to monitoring close, contributes entries to the history chain; every entry carries the previous entry's hash, forming an unbroken sequence across all conflicts system-wide. Verification walks the chain from the genesis entry, re-hashing each entry and comparing — any alteration anywhere breaks every subsequent link, making tampering immediately detectable and precisely locatable. The chain is checkpointed at intervals: checkpoint hashes are published and witnessed, so even a total ledger rebuild can be verified against the checkpoints. Historical queries use the chain as the spine: \"show me every contradiction involving source S in 2025\" walks the chain filtering by the indexed fields. Chain verification runs continuously as a background integrity process, with any break triggering the integrity incident procedure and freezing affected resolutions pending investigation. The chain's existence is what makes \"trust the history\" a verifiable claim rather than a slogan.", "key_points": ["Every contradiction entry hash-links to its predecessor: one tamper-evident chain.", "Verification walks and re-hashes; breaks are immediately locatable.", "Published checkpoints let even rebuilt ledgers prove integrity.", "Continuous background verification; breaks freeze affected resolutions."], "requirements": "The chain entry format; checkpoint publication; continuous verification process; incident procedure.", "standards": "Chain breaks trigger integrity incidents and resolution freezes. Checkpoints witnessed.", "citations": ["Signature history chain specification (Signature-labeled)", "Hash-chained audit logs (public reference)"]}}, {"topic": "Signature-Weighted Consensus for Time-Dependent Facts", "cat": "provenance-weighting", "rank": 5, "tier": "Advanced", "name": "time-weighted-consensus", "desc": "For facts that change over time, Signature consensus is computed per time segment: the provenance-weighted procedure runs independently on each segment of the timeline, so a source authoritative in 2019 does not outvote a source authoritative in 2024 about 2024. This record gives the segmentation procedure, the per-segment weighting with time decay anchored to each segment, and the timeline assembly. It is the meeting point of time-anchored resolution and provenance weighting — the full Signature treatment of facts that expire.", "body": {"how_it_works": "Segment the timeline at every point where the evidence changes: new observations, retractions, known world-events (elections, launches), and interval boundaries from the time-anchored claims. For each segment, assemble the claims whose valid intervals cover it and run provenance-weighted resolution restricted to that segment — with time decay computed relative to the segment's date, so each segment judges its sources by their freshness then. Segments with no covering claims are marked unknown; segments with single uncontested claims are confirmed by the verification passes alone. Assemble the segment verdicts into the canonical timeline, checking segment-boundary consistency (a claim winning adjacent segments with a gap between is flagged for review). The timeline carries per-segment verdict references, so any segment can be re-opened independently when new evidence targets it. Cross-segment patterns — a source systematically losing recent segments — feed the source calibration records.", "key_points": ["Consensus computed per time segment, not once for all time.", "Time decay anchored to each segment's date: freshness judged then, not now.", "Segments are independently re-openable; verdicts reference per segment.", "Cross-segment patterns feed source calibration."], "requirements": "Timeline segmentation rules; per-segment resolution; segment-boundary consistency checks.", "standards": "No atemporal verdicts for time-dependent facts. Unknown segments marked, never interpolated.", "citations": ["Signature time-weighted consensus (Signature-labeled)", "Temporal data fusion (public reference)"]}}, {"topic": "The Signature Resolution Oath", "cat": "arbitration", "rank": 5, "tier": "Advanced", "name": "resolution-oath", "desc": "The Signature resolution oath is the operator's personal commitment, taken before handling conflicts and renewed annually: to follow the procedure over preference, to preserve losing claims, to abstain when the evidence requires it, and to report pressure to do otherwise. This record gives the oath text, the taking ceremony, and the accountability it creates. Procedures constrain actions; the oath constrains the will behind the actions — it is the human layer of Signature trust, and it is taken seriously.", "body": {"how_it_works": "New operators study the full procedure corpus, pass the drill battery, and then take the oath before witnesses: \"I will let the procedure decide where the evidence does not; I will preserve what loses; I will abstain where I cannot resolve; I will report any pressure to force an answer; I will sign my name to my verdicts.\" The signed oath is ledger-recorded with the operator's certification. Annual renewal includes the year's case review: the operator's verdicts are sampled and replayed, abstention discipline is checked (did they abstain where required?), and any forced-answer findings are addressed before renewal. Violations of the oath — forced answers, deleted claims, unsigned verdicts — are treated as the most serious non-technical failures in the system, because they attack trust itself. The oath does not replace the procedure's mechanical guarantees; it covers the territory mechanics cannot reach: the operator's intent.", "key_points": ["The oath binds intent: procedure over preference, preservation, abstention, reporting pressure.", "Taken before witnesses, ledger-recorded, renewed annually with case review.", "Violations are the most serious non-technical failures — they attack trust itself.", "The oath covers what mechanics cannot: the operator's will."], "requirements": "The oath text; the taking ceremony; annual renewal with case review; violation handling.", "standards": "No unsupervised high-stakes work without a current oath. Violations ledger-recorded.", "citations": ["Signature operator oath (Signature-labeled)", "Professional oaths as accountability mechanisms (public reference)"]}}];
function demoFor(e){
  var L=['RECORD: '+DBTITLE+': '+e.topic,'ID: '+PREFIX+'(seed)','CATEGORY: '+e.cat+' | LADDER: '+e.rank+' ('+e.tier+')','HOW IT WORKS: '+e.body.how_it_works,'KEY POINTS:'];
  e.body.key_points.forEach(function(k,i){L.push('  '+(i+1)+'. '+k);});
  L.push('REQUIREMENTS: '+e.body.requirements);
  L.push('STANDARDS: '+e.body.standards);
  L.push('CITATIONS: '+e.body.citations.join(' | '));
  return 'console.log('+JSON.stringify(L.join('\n'))+');';
}
function generate(seed,opts){
  opts=opts||{};
  var n=DATA.length;
  var e=DATA[(seed-1)%n];
  if(opts.category&&e.cat!==opts.category){ for(var i=0;i<n;i++){ var c=DATA[(seed-1+i)%n]; if(c.cat===opts.category){ e=c; break; } } }
  var cycle=Math.floor((seed-1)/n);
  var rec={
    id:PREFIX+String(seed).padStart(6,'0'),
    name:e.name,
    title:DBTITLE+': '+e.topic+(cycle>0?' (variant '+cycle+')':''),
    description:e.desc,
    category:e.cat,
    ladder:e.rank,
    ladder_rank:e.rank,
    ladder_tier:e.tier,
    src:SRC,
    src_detail:SRC_DETAIL,
    seed:seed,
    how_it_works:e.body.how_it_works,
    key_points:e.body.key_points.slice(),
    requirements:e.body.requirements,
    standards:e.body.standards,
    citations:e.body.citations.slice(),
    demo:{program:demoFor(e)}
  };
  return rec;
}
function escRx(s){return s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');}
function validate(r){
  var errs=[];
  if(!r||typeof r!=='object')return {ok:false,errors:['not an object']};
  if(!new RegExp('^'+escRx(PREFIX)+'\\d{6}$').test(r.id||''))errs.push('id');
  if(typeof r.title!=='string'||r.title.indexOf(DBTITLE)!==0)errs.push('title');
  if(CATS.indexOf(r.category)<0)errs.push('category');
  if(!(r.ladder>=1&&r.ladder<=5))errs.push('ladder');
  if(r.src!==SRC)errs.push('src');
  if(typeof r.description!=='string'||r.description.length<200)errs.push('description<200');
  REQUIRED.forEach(function(k){if(r[k]===undefined||r[k]===null)errs.push('missing:'+k);});
  if(!Array.isArray(r.key_points)||!r.key_points.length)errs.push('key_points');
  if(!Array.isArray(r.citations)||!r.citations.length)errs.push('citations');
  if(!r.demo||typeof r.demo.program!=='string'||!r.demo.program.length)errs.push('demo');
  if(/lorem ipsum/i.test(JSON.stringify(r)))errs.push('placeholder');
  return {ok:errs.length===0,errors:errs};
}
function driftCheck(rec,sample){
  var dups=(sample||[]).filter(function(x){return x&&x.title===rec.title&&x.category===rec.category;});
  return dups.length?{ok:false,errors:['duplicate title+category already in archive']}:{ok:true,errors:[]};
}
var api={generate:generate,validate:validate,driftCheck:driftCheck,slug:'fact-conflict-contradiction-resolution-signature',version:'jahdb-fact-conflict-contradiction-resolution-signature-1.0'};
if(typeof module!=='undefined'&&module.exports)module.exports=api;
if(typeof window!=='undefined'){
  window["jahdb_fact_conflict_contradiction_resolution_signature"]=api;
  try{if(window.JAHDB&&JAHDB.registerGenerator)JAHDB.registerGenerator('fact-conflict-contradiction-resolution-signature',api);}catch(e){}
}
})();
